/*demo:i18n*/Object.entries({"en":{"nDemo":"Demo","dEy":"Step-by-step demo","dH":"Build a character, from an empty file to an exported film","dP":"Meet the walking person that the studio opens on first start. We build it in eleven stages, and every stage is the same project cut after that step: osatura demo-person writes the finished one. The commands ran on the real osatura binary, and every picture is a frame the engine rendered.","dPrev":"Back","dNext":"Next","dPlay":"Play","dPause":"Pause","dAuto":"Run all","dStop":"Stop","dTerm":"Terminal","dScript":"Script","dStep":"Step {n} / {m}","dFrame":"frame {n} / {m}","dNote":"Real output of {engine}: the commands ran on the actual binary and every picture is a frame rendered by the engine, not a hand-drawn animation. The stage-NN.json files are cuts of the finished project that osatura demo-person writes.","dS1":"An empty project","dD1":"A few JSON keys are a whole project: 640×480, 24 frames per second, 32 frames. check confirms it is valid.","dS2":"The scenery","dD2":"Sky, sun, hills, meadow, fence and ground marks: layers drawn back to front, with gradients and a sun that blends with Screen.","dS3":"Body and legs","dD3":"Pelvis, torso, neck and two legs with shoes: closed smooth paths with an ink outline. The far side is drawn first and darker, so the near side reads in front.","dS4":"Head and face","dD4":"Head, ear, hair, ponytail, brow, nostril and a blush. The eye and the mouth are switch layers: open or closed eye, smile or open mouth.","dS5":"Arms, hands, five fingers","dD5":"Each arm is a skinned outline, plus a sleeve and a palm. Every hand has four fingers and a thumb, each a small outline of its own.","dS6":"The skeleton","dD6":"Forty-two bones with parents. Each piece rides its bone, and limbs are skinned with a blend at the joint, so elbows and knees bend smoothly. The dots are the bones.","dS7":"The legs walk","dD7":"Keys on hip, knee, ankle and toes follow a gait: heel strike, flat foot, heel-off, swing. The hips bob. The feet still slide, because the ground does not move yet.","dS8":"The arms swing","dD8":"Arms swing against the legs. The elbows bend more on the forward swing, and hands and fingers trail a little behind.","dS9":"Trunk, head and ponytail","dD9":"Spine, chest, neck and head counter-rotate so the head stays level. The ear and the ponytail follow late and overshoot a little.","dS10":"A blink and a smile","dD10":"Switch keys choose which eye and which mouth show on each frame. This is also what the lip-sync commands write for you.","dS11":"The ground moves","dD11":"The ground marks and the fence scroll exactly as fast as the planted foot moves back, and the shadow follows the bob. The feet no longer slide: this is the finished example.","dS12":"Check it","dD12":"lint runs static checks on the rig and the animation; stats summarises the project.","dS13":"Export","dD13":"The same project becomes a GIF, a self-contained HTML player or a Lottie file."},"ro":{"nDemo":"Demo","dEy":"Demo pas cu pas","dH":"Construiește un personaj, de la un fișier gol la un film exportat","dP":"Iată persoana care merge, cea cu care se deschide studioul la prima pornire. O construim în unsprezece etape; fiecare etapă este același proiect, tăiat după pasul respectiv, iar osatura demo-person îl scrie pe cel terminat. Comenzile au rulat pe binarul real osatura, iar fiecare imagine este un cadru randat de motor.","dPrev":"Înapoi","dNext":"Înainte","dPlay":"Redă","dPause":"Pauză","dAuto":"Rulează tot","dStop":"Oprește","dTerm":"Terminal","dScript":"Script","dStep":"Pasul {n} / {m}","dFrame":"cadru {n} / {m}","dNote":"Ieșire reală din {engine}: comenzile au rulat pe binarul real, iar fiecare imagine este un cadru randat de motor, nu o animație desenată de mână. Fișierele stage-NN.json sunt tăieturi din proiectul terminat pe care îl scrie osatura demo-person.","dS1":"Un proiect gol","dD1":"Câteva chei JSON sunt un proiect întreg: 640×480, 24 de cadre pe secundă, 32 de cadre. check confirmă că e valid.","dS2":"Decorul","dD2":"Cer, soare, dealuri, pajiște, gard și semne pe sol: straturi desenate din spate în față, cu gradienți și un soare care se amestecă prin Screen.","dS3":"Corpul și picioarele","dD3":"Bazin, trunchi, gât și două picioare cu pantofi: trasee netede închise, cu contur de cerneală. Partea îndepărtată se desenează întâi și mai închis, ca partea apropiată să stea în față.","dS4":"Capul și fața","dD4":"Cap, ureche, păr, coadă, sprânceană, nară și un obraz rumen. Ochiul și gura sunt straturi „switch”: ochi deschis sau închis, zâmbet sau gură deschisă.","dS5":"Brațe, mâini, cinci degete","dD5":"Fiecare braț este un contur „skinned”, plus o mânecă și o palmă. Fiecare mână are patru degete și un police, fiecare cu conturul lui.","dS6":"Scheletul","dD6":"Patruzeci și două de oase cu părinți. Fiecare piesă merge cu osul ei, iar membrele sunt „skinned” cu un amestec la articulație, deci coatele și genunchii se îndoaie fin. Punctele sunt oasele.","dS7":"Picioarele merg","dD7":"Chei pe șold, genunchi, gleznă și degetele piciorului urmează un tipar de mers: lovirea cu călcâiul, talpa plată, desprinderea, balansul. Șoldurile se leagănă. Picioarele încă alunecă, fiindcă solul nu se mișcă încă.","dS8":"Brațele se balansează","dD8":"Brațele se balansează în opoziție cu picioarele. Coatele se îndoaie mai mult la balansul înainte, iar mâinile și degetele rămân puțin în urmă.","dS9":"Trunchi, cap și coadă","dD9":"Coloana, pieptul, gâtul și capul se rotesc în sens opus, ca să rămână capul drept. Urechea și coada urmează cu întârziere și trec puțin dincolo.","dS10":"Un clipit și un zâmbet","dD10":"Cheile „switch” aleg ce ochi și ce gură se văd în fiecare cadru. Asta scriu și comenzile de lip-sync în locul tău.","dS11":"Solul se mișcă","dD11":"Semnele de pe sol și gardul se derulează exact cât de repede se duce înapoi piciorul sprijinit, iar umbra urmărește legănarea. Picioarele nu mai alunecă: acesta este exemplul terminat.","dS12":"Verifică","dD12":"lint face verificări statice pe schelet și pe animație; stats rezumă proiectul.","dS13":"Export","dD13":"Același proiect devine un GIF, un player HTML de sine stătător sau un fișier Lottie."},"fr":{"nDemo":"Démo","dEy":"Démo pas à pas","dH":"Construire un personnage, d’un fichier vide à un film exporté","dP":"Voici la personne qui marche, celle que le studio ouvre au premier démarrage. Nous la construisons en onze étapes ; chaque étape est le même projet, coupé après l’étape, et osatura demo-person écrit le projet terminé. Les commandes ont été exécutées sur le vrai binaire osatura, et chaque image a été rendue par le moteur.","dPrev":"Retour","dNext":"Suivant","dPlay":"Lire","dPause":"Pause","dAuto":"Tout lancer","dStop":"Arrêter","dTerm":"Terminal","dScript":"Script","dStep":"Étape {n} / {m}","dFrame":"image {n} / {m}","dNote":"Sortie réelle de {engine} : les commandes ont été exécutées sur le vrai binaire et chaque image a été rendue par le moteur, pas une animation dessinée à la main. Les fichiers stage-NN.json sont des coupes du projet terminé qu’écrit osatura demo-person.","dS1":"Un projet vide","dD1":"Quelques clés JSON font un projet entier : 640×480, 24 images par seconde, 32 images. check confirme qu’il est valide.","dS2":"Le décor","dD2":"Ciel, soleil, collines, prairie, clôture et repères au sol : des calques dessinés de l’arrière vers l’avant, avec des dégradés et un soleil en mode Screen.","dS3":"Corps et jambes","dD3":"Bassin, torse, cou et deux jambes avec chaussures : des tracés lissés fermés, avec un contour d’encre. Le côté éloigné est dessiné d’abord et plus sombre, pour que le côté proche passe devant.","dS4":"Tête et visage","dD4":"Tête, oreille, cheveux, queue de cheval, sourcil, narine et une joue rosée. L’œil et la bouche sont des calques « switch » : œil ouvert ou fermé, sourire ou bouche ouverte.","dS5":"Bras, mains, cinq doigts","dD5":"Chaque bras est un contour « skinned », avec une manche et une paume. Chaque main a quatre doigts et un pouce, chacun avec son propre contour.","dS6":"Le squelette","dD6":"Quarante-deux os avec des parents. Chaque pièce suit son os, et les membres sont « skinned » avec un mélange à l’articulation : coudes et genoux plient en douceur. Les points sont les os.","dS7":"Les jambes marchent","dD7":"Des clés sur la hanche, le genou, la cheville et les orteils suivent une démarche : attaque du talon, pied à plat, décollement, oscillation. Le bassin ondule. Les pieds glissent encore, car le sol ne bouge pas.","dS8":"Les bras balancent","dD8":"Les bras balancent en opposition aux jambes. Les coudes plient davantage à l’avant, et les mains et les doigts traînent un peu derrière.","dS9":"Tronc, tête et queue de cheval","dD9":"Colonne, poitrine, cou et tête tournent en sens inverse pour garder la tête droite. L’oreille et la queue de cheval suivent en retard et dépassent un peu.","dS10":"Un clignement et un sourire","dD10":"Des clés « switch » choisissent l’œil et la bouche visibles à chaque image. C’est aussi ce que les commandes de lip-sync écrivent pour vous.","dS11":"Le sol bouge","dD11":"Les repères du sol et la clôture défilent exactement aussi vite que le pied posé recule, et l’ombre suit l’ondulation. Les pieds ne glissent plus : voici l’exemple terminé.","dS12":"Vérifier","dD12":"lint fait des vérifications statiques du squelette et de l’animation ; stats résume le projet.","dS13":"Exporter","dD13":"Le même projet devient un GIF, un lecteur HTML autonome ou un fichier Lottie."},"it":{"nDemo":"Demo","dEy":"Demo passo dopo passo","dH":"Costruire un personaggio, da un file vuoto a un film esportato","dP":"Ecco la persona che cammina, quella con cui lo studio si apre al primo avvio. La costruiamo in undici fasi; ogni fase è lo stesso progetto, tagliato dopo quel passo, e osatura demo-person scrive quello finito. I comandi sono stati eseguiti sul vero binario osatura, e ogni immagine è un fotogramma reso dal motore.","dPrev":"Indietro","dNext":"Avanti","dPlay":"Riproduci","dPause":"Pausa","dAuto":"Esegui tutto","dStop":"Ferma","dTerm":"Terminale","dScript":"Script","dStep":"Passo {n} / {m}","dFrame":"fotogramma {n} / {m}","dNote":"Output reale di {engine}: i comandi sono stati eseguiti sul vero binario e ogni immagine è un fotogramma reso dal motore, non un’animazione disegnata a mano. I file stage-NN.json sono tagli del progetto finito che scrive osatura demo-person.","dS1":"Un progetto vuoto","dD1":"Poche chiavi JSON sono un intero progetto: 640×480, 24 fotogrammi al secondo, 32 fotogrammi. check conferma che è valido.","dS2":"Lo scenario","dD2":"Cielo, sole, colline, prato, recinto e segni sul terreno: livelli disegnati dal fondo in avanti, con gradienti e un sole in modalità Screen.","dS3":"Corpo e gambe","dD3":"Bacino, busto, collo e due gambe con scarpe: tracciati lisci chiusi, con un contorno a inchiostro. Il lato lontano si disegna prima e più scuro, così il lato vicino sta davanti.","dS4":"Testa e viso","dD4":"Testa, orecchio, capelli, coda di cavallo, sopracciglio, narice e una guancia rosata. L’occhio e la bocca sono livelli «switch»: occhio aperto o chiuso, sorriso o bocca aperta.","dS5":"Braccia, mani, cinque dita","dD5":"Ogni braccio è un contorno «skinned», più una manica e un palmo. Ogni mano ha quattro dita e un pollice, ciascuno con il proprio contorno.","dS6":"Lo scheletro","dD6":"Quarantadue ossa con genitori. Ogni pezzo segue il suo osso e gli arti sono «skinned» con una sfumatura all’articolazione: gomiti e ginocchia si piegano con dolcezza. I punti sono le ossa.","dS7":"Le gambe camminano","dD7":"Chiavi su anca, ginocchio, caviglia e dita del piede seguono un’andatura: contatto del tallone, piede piatto, stacco, oscillazione. Il bacino ondeggia. I piedi scivolano ancora, perché il terreno non si muove.","dS8":"Le braccia oscillano","dD8":"Le braccia oscillano in opposizione alle gambe. I gomiti si piegano di più in avanti, e mani e dita restano un poco indietro.","dS9":"Busto, testa e coda","dD9":"Colonna, petto, collo e testa ruotano in senso opposto per tenere la testa dritta. L’orecchio e la coda seguono in ritardo e vanno un po’ oltre.","dS10":"Un battito di ciglia e un sorriso","dD10":"Le chiavi «switch» scelgono quale occhio e quale bocca si vedono a ogni fotogramma. È anche ciò che scrivono per te i comandi di lip-sync.","dS11":"Il terreno si muove","dD11":"I segni sul terreno e il recinto scorrono esattamente veloci quanto il piede appoggiato arretra, e l’ombra segue l’ondeggiamento. I piedi non scivolano più: questo è l’esempio finito.","dS12":"Verifica","dD12":"lint esegue controlli statici su scheletro e animazione; stats riassume il progetto.","dS13":"Esporta","dD13":"Lo stesso progetto diventa una GIF, un player HTML autonomo o un file Lottie."},"es":{"nDemo":"Demo","dEy":"Demo paso a paso","dH":"Construir un personaje, de un archivo vacío a una película exportada","dP":"Esta es la persona que camina, con la que el estudio se abre en el primer arranque. La construimos en once etapas; cada etapa es el mismo proyecto, cortado tras ese paso, y osatura demo-person escribe el terminado. Los comandos se ejecutaron en el binario real osatura, y cada imagen es un fotograma renderizado por el motor.","dPrev":"Atrás","dNext":"Siguiente","dPlay":"Reproducir","dPause":"Pausa","dAuto":"Ejecutar todo","dStop":"Detener","dTerm":"Terminal","dScript":"Script","dStep":"Paso {n} / {m}","dFrame":"fotograma {n} / {m}","dNote":"Salida real de {engine}: los comandos se ejecutaron en el binario real y cada imagen es un fotograma renderizado por el motor, no una animación dibujada a mano. Los archivos stage-NN.json son cortes del proyecto terminado que escribe osatura demo-person.","dS1":"Un proyecto vacío","dD1":"Unas pocas claves JSON son un proyecto entero: 640×480, 24 fotogramas por segundo, 32 fotogramas. check confirma que es válido.","dS2":"El escenario","dD2":"Cielo, sol, colinas, prado, valla y marcas en el suelo: capas dibujadas de atrás hacia delante, con degradados y un sol en modo Screen.","dS3":"Cuerpo y piernas","dD3":"Pelvis, torso, cuello y dos piernas con zapatos: trazados suaves cerrados con contorno de tinta. El lado lejano se dibuja primero y más oscuro, para que el cercano quede delante.","dS4":"Cabeza y rostro","dD4":"Cabeza, oreja, pelo, coleta, ceja, fosa nasal y un rubor. El ojo y la boca son capas «switch»: ojo abierto o cerrado, sonrisa o boca abierta.","dS5":"Brazos, manos, cinco dedos","dD5":"Cada brazo es un contorno «skinned», más una manga y una palma. Cada mano tiene cuatro dedos y un pulgar, cada uno con su propio contorno.","dS6":"El esqueleto","dD6":"Cuarenta y dos huesos con padres. Cada pieza va con su hueso y las extremidades son «skinned» con una mezcla en la articulación: codos y rodillas se doblan con suavidad. Los puntos son los huesos.","dS7":"Las piernas caminan","dD7":"Claves en cadera, rodilla, tobillo y dedos del pie siguen una marcha: apoyo del talón, pie plano, despegue, balanceo. La pelvis ondula. Los pies aún resbalan, porque el suelo no se mueve.","dS8":"Los brazos se balancean","dD8":"Los brazos se balancean en oposición a las piernas. Los codos se doblan más al ir hacia delante, y manos y dedos se quedan un poco atrás.","dS9":"Tronco, cabeza y coleta","dD9":"Columna, pecho, cuello y cabeza giran en sentido contrario para mantener la cabeza recta. La oreja y la coleta siguen tarde y se pasan un poco.","dS10":"Un parpadeo y una sonrisa","dD10":"Las claves «switch» eligen qué ojo y qué boca se ven en cada fotograma. Es también lo que escriben por ti los comandos de lip-sync.","dS11":"El suelo se mueve","dD11":"Las marcas del suelo y la valla se desplazan exactamente tan rápido como retrocede el pie apoyado, y la sombra sigue la ondulación. Los pies ya no resbalan: este es el ejemplo terminado.","dS12":"Comprobar","dD12":"lint hace comprobaciones estáticas del esqueleto y la animación; stats resume el proyecto.","dS13":"Exportar","dD13":"El mismo proyecto se convierte en un GIF, un reproductor HTML autónomo o un archivo Lottie."},"pt":{"nDemo":"Demo","dEy":"Demo passo a passo","dH":"Construir um personagem, de um arquivo vazio a um filme exportado","dP":"Esta é a pessoa que caminha, com a qual o estúdio abre na primeira execução. Nós a construímos em onze etapas; cada etapa é o mesmo projeto, cortado depois desse passo, e osatura demo-person grava o projeto terminado. Os comandos rodaram no binário real osatura, e cada imagem é um quadro renderizado pelo motor.","dPrev":"Voltar","dNext":"Próximo","dPlay":"Reproduzir","dPause":"Pausa","dAuto":"Executar tudo","dStop":"Parar","dTerm":"Terminal","dScript":"Script","dStep":"Passo {n} / {m}","dFrame":"quadro {n} / {m}","dNote":"Saída real de {engine}: os comandos rodaram no binário real e cada imagem é um quadro renderizado pelo motor, não uma animação desenhada à mão. Os arquivos stage-NN.json são cortes do projeto terminado que osatura demo-person grava.","dS1":"Um projeto vazio","dD1":"Poucas chaves JSON formam um projeto inteiro: 640×480, 24 quadros por segundo, 32 quadros. check confirma que é válido.","dS2":"O cenário","dD2":"Céu, sol, colinas, prado, cerca e marcas no chão: camadas desenhadas de trás para a frente, com gradientes e um sol em modo Screen.","dS3":"Corpo e pernas","dD3":"Bacia, tronco, pescoço e duas pernas com sapatos: caminhos suaves fechados, com contorno de tinta. O lado distante é desenhado primeiro e mais escuro, para que o lado próximo fique na frente.","dS4":"Cabeça e rosto","dD4":"Cabeça, orelha, cabelo, rabo de cavalo, sobrancelha, narina e um rubor. O olho e a boca são camadas «switch»: olho aberto ou fechado, sorriso ou boca aberta.","dS5":"Braços, mãos, cinco dedos","dD5":"Cada braço é um contorno «skinned», mais uma manga e uma palma. Cada mão tem quatro dedos e um polegar, cada um com seu próprio contorno.","dS6":"O esqueleto","dD6":"Quarenta e dois ossos com pais. Cada peça acompanha seu osso e os membros são «skinned» com uma mistura na articulação: cotovelos e joelhos dobram com suavidade. Os pontos são os ossos.","dS7":"As pernas caminham","dD7":"Chaves no quadril, joelho, tornozelo e dedos do pé seguem uma marcha: contato do calcanhar, pé plano, impulso, balanço. O quadril oscila. Os pés ainda escorregam, porque o chão ainda não se move.","dS8":"Os braços balançam","dD8":"Os braços balançam em oposição às pernas. Os cotovelos dobram mais ao ir para a frente, e mãos e dedos ficam um pouco para trás.","dS9":"Tronco, cabeça e rabo de cavalo","dD9":"Coluna, peito, pescoço e cabeça giram em sentido contrário para manter a cabeça reta. A orelha e o rabo de cavalo seguem com atraso e passam um pouco do ponto.","dS10":"Uma piscadela e um sorriso","dD10":"As chaves «switch» escolhem qual olho e qual boca aparecem em cada quadro. É também o que os comandos de lip-sync escrevem para você.","dS11":"O chão se move","dD11":"As marcas do chão e a cerca se deslocam exatamente na velocidade com que o pé apoiado recua, e a sombra acompanha a oscilação. Os pés não escorregam mais: este é o exemplo terminado.","dS12":"Verificar","dD12":"lint faz verificações estáticas do esqueleto e da animação; stats resume o projeto.","dS13":"Exportar","dD13":"O mesmo projeto vira um GIF, um player HTML autônomo ou um arquivo Lottie."},"de":{"nDemo":"Demo","dEy":"Schritt-für-Schritt-Demo","dH":"Eine Figur bauen, von der leeren Datei zum exportierten Film","dP":"Das ist die gehende Person, mit der sich das Studio beim ersten Start öffnet. Wir bauen sie in elf Stufen; jede Stufe ist dasselbe Projekt, nach diesem Schritt abgeschnitten, und osatura demo-person schreibt das fertige. Die Befehle liefen auf dem echten osatura-Binary, und jedes Bild ist ein von der Engine gerendertes Frame.","dPrev":"Zurück","dNext":"Weiter","dPlay":"Abspielen","dPause":"Pause","dAuto":"Alles ausführen","dStop":"Stopp","dTerm":"Terminal","dScript":"Skript","dStep":"Schritt {n} / {m}","dFrame":"Bild {n} / {m}","dNote":"Echte Ausgabe von {engine}: Die Befehle liefen auf dem echten Binary, und jedes Bild ist ein von der Engine gerendertes Frame, keine von Hand gezeichnete Animation. Die Dateien stage-NN.json sind Schnitte des fertigen Projekts, das osatura demo-person schreibt.","dS1":"Ein leeres Projekt","dD1":"Ein paar JSON-Schlüssel sind ein ganzes Projekt: 640×480, 24 Bilder pro Sekunde, 32 Bilder. check bestätigt, dass es gültig ist.","dS2":"Die Kulisse","dD2":"Himmel, Sonne, Hügel, Wiese, Zaun und Bodenmarken: Ebenen von hinten nach vorn, mit Verläufen und einer Sonne im Modus Screen.","dS3":"Körper und Beine","dD3":"Becken, Rumpf, Hals und zwei Beine mit Schuhen: geschlossene, glatte Pfade mit Tuschekontur. Die ferne Seite wird zuerst und dunkler gezeichnet, damit die nahe vorn liegt.","dS4":"Kopf und Gesicht","dD4":"Kopf, Ohr, Haar, Pferdeschwanz, Braue, Nasenloch und etwas Rouge. Auge und Mund sind Switch-Ebenen: Auge offen oder zu, Lächeln oder offener Mund.","dS5":"Arme, Hände, fünf Finger","dD5":"Jeder Arm ist eine Skinned-Kontur, dazu ein Ärmel und eine Handfläche. Jede Hand hat vier Finger und einen Daumen, jeder mit eigener Kontur.","dS6":"Das Skelett","dD6":"Zweiundvierzig Knochen mit Eltern. Jedes Teil folgt seinem Knochen, und die Gliedmaßen sind am Gelenk mit einer Überblendung geskinnt, sodass Ellbogen und Knie weich beugen. Die Punkte sind die Knochen.","dS7":"Die Beine gehen","dD7":"Keys an Hüfte, Knie, Knöchel und Zehen folgen einem Gangbild: Fersenaufsatz, Fußsohle flach, Abdruck, Schwung. Das Becken wippt. Die Füße rutschen noch, weil sich der Boden nicht bewegt.","dS8":"Die Arme schwingen","dD8":"Die Arme schwingen gegen die Beine. Die Ellbogen beugen vorn stärker, und Hände und Finger bleiben etwas zurück.","dS9":"Rumpf, Kopf und Pferdeschwanz","dD9":"Wirbelsäule, Brust, Hals und Kopf drehen gegenläufig, damit der Kopf waagerecht bleibt. Ohr und Pferdeschwanz folgen spät und schwingen etwas über.","dS10":"Ein Blinzeln und ein Lächeln","dD10":"Switch-Keys wählen, welches Auge und welcher Mund in jedem Frame zu sehen sind. Das schreiben auch die Lip-Sync-Befehle für dich.","dS11":"Der Boden bewegt sich","dD11":"Bodenmarken und Zaun laufen genau so schnell, wie der aufgesetzte Fuß zurückweicht, und der Schatten folgt dem Wippen. Die Füße rutschen nicht mehr: das ist das fertige Beispiel.","dS12":"Prüfen","dD12":"lint führt statische Prüfungen von Rig und Animation aus; stats fasst das Projekt zusammen.","dS13":"Exportieren","dD13":"Dasselbe Projekt wird zu einem GIF, einem eigenständigen HTML-Player oder einer Lottie-Datei."},"hu":{"nDemo":"Demó","dEy":"Lépésről lépésre demó","dH":"Karakter építése, az üres fájltól az exportált filmig","dP":"Íme a sétáló alak, amellyel a stúdió első indításkor megnyílik. Tizenegy lépésben építjük fel; minden szakasz ugyanaz a projekt, az adott lépés után elvágva, a késznek az osatura demo-person írja ki. A parancsok a valódi osatura binárison futottak, és minden kép a motor által renderelt kocka.","dPrev":"Vissza","dNext":"Tovább","dPlay":"Lejátszás","dPause":"Szünet","dAuto":"Mindent futtat","dStop":"Leállítás","dTerm":"Terminál","dScript":"Szkript","dStep":"{n}. lépés / {m}","dFrame":"{n}. kocka / {m}","dNote":"A {engine} valódi kimenete: a parancsok a valódi binárison futottak, és minden kép a motor által renderelt kocka, nem kézzel rajzolt animáció. A stage-NN.json fájlok az osatura demo-person által írt kész projekt szeletei.","dS1":"Üres projekt","dD1":"Néhány JSON-kulcs egy egész projekt: 640×480, 24 kocka másodpercenként, 32 kocka. A check megerősíti, hogy érvényes.","dS2":"A díszlet","dD2":"Égbolt, nap, dombok, rét, kerítés és talajjelek: hátulról előre rajzolt rétegek, színátmenetekkel és Screen módú nappal.","dS3":"Test és lábak","dD3":"Medence, törzs, nyak és két láb cipővel: zárt, sima útvonalak tintavonallal. A távolabbi oldal előbb és sötétebben készül, hogy a közelebbi előtte látsszon.","dS4":"Fej és arc","dD4":"Fej, fül, haj, lófarok, szemöldök, orrlyuk és egy kis pír. A szem és a száj switch réteg: nyitott vagy csukott szem, mosoly vagy nyitott száj.","dS5":"Karok, kezek, öt ujj","dD5":"Minden kar skinned körvonal, hozzá ruhaujj és tenyér. Minden kézen négy ujj és egy hüvelykujj van, mindegyik saját körvonallal.","dS6":"A csontváz","dD6":"Negyvenkét csont szülőkkel. Minden darab a csontjával mozog, a végtagok az ízületnél átfedéssel skinneltek, így a könyök és a térd simán hajlik. A pontok a csontok.","dS7":"A lábak járnak","dD7":"A csípő, térd, boka és lábujjak kulcsai egy járásmintát követnek: sarokleérkezés, lapos talp, elrugaszkodás, lendítés. A medence ring. A lábak még csúsznak, mert a talaj még nem mozog.","dS8":"A karok lendülnek","dD8":"A karok a lábakkal ellentétesen lendülnek. A könyök előre lendüléskor jobban hajlik, a kéz és az ujjak kissé lemaradnak.","dS9":"Törzs, fej és lófarok","dD9":"A gerinc, mell, nyak és fej ellentétesen fordul, hogy a fej vízszintes maradjon. A fül és a lófarok késve követ, és kicsit túllendül.","dS10":"Pislogás és mosoly","dD10":"A switch kulcsok választják ki, melyik szem és száj látszik minden kockán. Ezt írják helyetted a szájszinkron parancsok is.","dS11":"A talaj mozog","dD11":"A talajjelek és a kerítés pontosan olyan gyorsan gördülnek, ahogy a talpon álló láb hátrébb megy, az árnyék pedig követi a ringást. A lábak már nem csúsznak: ez a kész példa.","dS12":"Ellenőrzés","dD12":"A lint statikus ellenőrzést végez a csontvázon és az animáción; a stats összefoglalja a projektet.","dS13":"Exportálás","dD13":"Ugyanebből a projektből GIF, önálló HTML-lejátszó vagy Lottie-fájl lesz."}}).forEach(([l,o])=>Object.assign(T[l],o));/*/demo:i18n*/
Object.keys(T).forEach(l=>{if(l!=='en')Object.setPrototypeOf(T[l],T.en)});
let L=(()=>{if(window.OSA_LANG&&T[window.OSA_LANG])return window.OSA_LANG;try{const s=localStorage.getItem('l');if(s&&T[s])return s}catch(e){}return'en'})();
function applyLang(){
  const t=T[L];document.documentElement.lang=L;
  // the build prerenders these texts in the page language; rewriting them again would only repaint (and delay LCP)
  const pre=!applyLang.ran&&(window.OSA_LANG||'en')===L;applyLang.ran=true;
  if(!pre){$$('[data-i]').forEach(e=>{e.innerHTML=t[e.dataset.i]});
  $('#vy').innerHTML=t.vy.map(x=>`<li>${x}</li>`).join('');$('#vx').innerHTML=t.vx.map(x=>`<li>${x}</li>`).join('');}
  $$('[data-ph]').forEach(e=>e.placeholder=t[e.dataset.ph]);
  $$('[data-al]').forEach(e=>{if(t[e.dataset.al])e.setAttribute('aria-label',t[e.dataset.al])});$$('.pt').forEach(e=>e.title=t.tiPartial||'partial');
  // accessible names must contain the visible text (WCAG 2.5.3)
  ['#lang','#rlang'].forEach(s=>$(s).setAttribute('aria-label',t.alLang+': '+L.toUpperCase()));
  $('#lang').textContent=L.toUpperCase()+' ▾';$('#rlang').textContent=L.toUpperCase()+' ▾';
  document.querySelector('meta[name=description]').content=t.metaDesc;if(!$('#reader').classList.contains('on'))document.title=t.metaTitle;
  updMatch();onLang&&onLang();
  try{localStorage.setItem('l',L)}catch(e){}
}
