/* theme colours for canvas */
let C={};
function cols(){const s=getComputedStyle(root),g=k=>s.getPropertyValue(k).trim();C={a:g('--a'),b:g('--b'),c:g('--c'),bg:g('--bg'),tx:g('--tx'),line:g('--line')}}
