  const com=HASHC.has(lang)?'(?<![^\\s])#[^\\n]*':SLASHC.has(lang)?'\\/\\/[^\\n]*':'(?!)';
  const re=new RegExp(`(${com})|("(?:[^"\\\\\\n]|\\\\.)*")|\\b([A-Za-z_]\\w*)\\b|\\b(\\d[\\d_.]*)\\b`,'g');
  let o='',last=0,m;
