    if(m[1])o+=`<span class="c">${esc(m[1])}</span>`;
    else if(m[2])o+=`<span class="s">${esc(m[2])}</span>`;
    else if(m[3])o+=KW.test(m[3])&&!HASHC.has(lang)?`<span class="k">${m[3]}</span>`:esc(m[3]);
