  return[{k:'act',t:t.act_theme,run:()=>$('#theme').click()},...LANGS.map(([c,n])=>({k:'act',t:`${t.langLabel}: ${n}`,run:()=>setLang(c)})),
    {k:'act',t:t.act_repo,run:()=>open(REPO,'_blank')},go('n1','#play'),go('nDemo','#demo'),go('nDocs','#docs'),go('nStudio','#studio'),go('nCli','#cli'),go('n5','#status')];
