/* ---- CLI atlas ---- */
let CMDS=[],csec='all',cq='';
function initCli(){
  const md=D.docs.CLI_REFERENCE.md,lines=md.split('\n'),o=outline(md),aMap={};o.forEach(h=>aMap[h.i]=h.a);
  let sec='',fence=false;
  for(let i=0;i<lines.length;i++){
    const ln=lines[i];
    if(/^\s*```/.test(ln)){fence=!fence;continue}if(fence)continue;
    let m=ln.match(/^## (.+)/);if(m){sec=plain(m[1]);continue}
    m=ln.match(/^### (.*`.*)/);
    if(m){
      const names=[...m[1].matchAll(/`([^`]+)`/g)].map(x=>x[1]);
      let d='',j=i+1,f=false;
      for(;j<lines.length;j++){const x=lines[j];
        if(/^\s*```/.test(x)){f=!f;continue}if(f)continue;
        if(/^#{1,6}\s/.test(x))break;
        if(/^\s*([|>]|[-*]\s)/.test(x)){if(d)break;continue}
        if(isBlank(x)){if(d&&!/^\*{0,2}Synopsis/i.test(d))break;if(/^\*{0,2}Synopsis/i.test(d))d='';continue}
        d+=(d?' ':'')+x.trim();
      }
      if(/^\*{0,2}Synopsis/i.test(d))d='';
      d=plain(d);if(d.length>150)d=d.slice(0,d.lastIndexOf(' ',148))+'…';
      CMDS.push({names,sec,d,a:aMap[i]});
    }
  }
}
function renderCli(){
  const secs=[...new Set(CMDS.map(c=>c.sec))];
  $('#cchips').innerHTML=`<button data-s="all" class="${csec==='all'?'on':''}">${T[L].all} (${CMDS.length})</button>`+secs.map(s=>{const lab=s.replace(/^\d+\.\s*/,'');return`<button data-s="${esc(s)}" class="${csec===s?'on':''}">${esc(lab.length>26?lab.slice(0,24)+'…':lab)} (${CMDS.filter(c=>c.sec===s).length})</button>`}).join('');
  const q=cq.toLowerCase(),list=CMDS.filter(c=>(csec==='all'||c.sec===csec)&&(!q||(c.names.join(' ')+' '+c.d).toLowerCase().includes(q)));
  $('#ccnt').textContent=`${list.length} ${T[L].of} ${CMDS.length}`;
  $('#atl').innerHTML=list.map(c=>`<a class="cmd" href="#/d/CLI_REFERENCE/${c.a}"><code>osatura ${esc(c.names.join(' · '))}</code><span>${esc(c.d)}</span></a>`).join('');
}
