  const q=lq.toLowerCase(),list=LIMS.filter(l=>(lsev==='all'||l.sev===lsev)&&(lsec==='all'||l.sec===lsec)&&(!q||(l.id+l.full+l.wk).toLowerCase().includes(q)));
